package com.tripmateai.controller; import com.tripmateai.dto.request.expense.*; import com.tripmateai.dto.response.*; import com.tripmateai.dto.response.expense.*; import com.tripmateai.service.ExpenseService; import com.tripmateai.util.ResponseUtils; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/trips/{tripId}/expenses") @RequiredArgsConstructor public class ExpenseController {private final ExpenseService service; @PostMapping public ResponseEntity<ApiResponse<ExpenseResponse>> create(@PathVariable Long tripId,@Valid @RequestBody ExpenseRequest r){return ResponseUtils.created(service.create(tripId,r),"Expense created");} @GetMapping public ResponseEntity<ApiResponse<Page<ExpenseResponse>>> list(@PathVariable Long tripId,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return ResponseUtils.success(service.list(tripId,page,size),"Expenses retrieved");} @GetMapping("/summary") public ResponseEntity<ApiResponse<ExpenseSummaryResponse>> summary(@PathVariable Long tripId){return ResponseUtils.success(service.summary(tripId),"Expense summary retrieved");} @GetMapping("/{expenseId}") public ResponseEntity<ApiResponse<ExpenseResponse>> get(@PathVariable Long tripId,@PathVariable Long expenseId){return ResponseUtils.success(service.get(tripId,expenseId),"Expense retrieved");} @PutMapping("/{expenseId}") public ResponseEntity<ApiResponse<ExpenseResponse>> update(@PathVariable Long tripId,@PathVariable Long expenseId,@Valid @RequestBody UpdateExpenseRequest r){return ResponseUtils.success(service.update(tripId,expenseId,r),"Expense updated");} @DeleteMapping("/{expenseId}") public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long tripId,@PathVariable Long expenseId){service.delete(tripId,expenseId);return ResponseUtils.success(null,"Expense deleted");}}
